mapper.select:
SELECT c.id AS companyId, c.company_name AS companyName, c.address AS address, c.lat AS lat, c.lng AS lng, COALESCE(c.owner_user_id, (SELECT u.user_id FROM sys_user u WHERE u.company_id = c.id AND u.is_deleted = 0 ORDER BY u.user_id ASC LIMIT 1) ) AS ownerUserId, c.company_type AS companyType, IFNULL(s.cnt, 0) AS supplyCount, IFNULL(r.cnt, 0) AS requirementCount, s.cats AS supplyCats, r.cats AS requirementCats, c.update_time AS updateTime FROM bus_company c LEFT JOIN ( SELECT company_id, COUNT(1) AS cnt, SUBSTRING_INDEX(GROUP_CONCAT(DISTINCT category_name ORDER BY category_name SEPARATOR ','), ',', 10) AS cats FROM bus_supply WHERE is_deleted = 0 AND status = 0 AND (expire_time IS NULL OR expire_time > NOW(3)) GROUP BY company_id ) s ON s.company_id = c.id LEFT JOIN ( SELECT company_id, COUNT(1) AS cnt, SUBSTRING_INDEX(GROUP_CONCAT(DISTINCT category_name ORDER BY category_name SEPARATOR ','), ',', 10) AS cats FROM bus_requirement WHERE is_deleted = 0 AND (expire_time IS NULL OR expire_time > NOW(3)) GROUP BY company_id ) r ON r.company_id = c.id WHERE c.is_deleted = 0
AND (c.company_name LIKE CONCAT('%', #{keyword}, '%') OR c.address LIKE CONCAT('%', #{keyword}, '%') OR EXISTS (SELECT 1 FROM bus_supply bs WHERE bs.company_id = c.id AND bs.is_deleted = 0 AND bs.status = 0 AND bs.category_name LIKE CONCAT('%', #{keyword}, '%') LIMIT 1) OR EXISTS (SELECT 1 FROM bus_requirement br WHERE br.company_id = c.id AND br.is_deleted = 0 AND br.category_name LIKE CONCAT('%', #{keyword}, '%') LIMIT 1))
AND c.province = #{province}
AND c.city = #{city}
AND c.company_type = #{companyType}
ORDER BY c.update_time DESC, c.id DESC
